import java.util.*;

public class Solution {
    // O(n + m): HashSet com os vistos, uma passada pelos comprados.
    static List<Long> naoVistos(List<Long> comprados, List<Long> vistos) {
        Set<Long> visto = new HashSet<>(vistos);
        List<Long> out = new ArrayList<>();
        for (Long id : comprados) if (!visto.contains(id)) out.add(id);
        return out;
    }
}

