import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void exemploDaAula() {
        assertEquals(List.of(20L, 40L), Solution.naoVistos(List.of(10L, 20L, 30L, 40L), List.of(30L, 99L, 10L)));
    }

    @Test void preservaOrdemERepeticoes() {
        assertEquals(List.of(5L, 7L, 5L), Solution.naoVistos(List.of(5L, 1L, 7L, 5L), List.of(1L)));
    }

    @Test void listasVazias() {
        assertEquals(List.of(), Solution.naoVistos(List.of(), List.of(1L)));
        assertEquals(List.of(3L), Solution.naoVistos(List.of(3L), List.of()));
    }

    @Test void grandeEmTempoLinear() {
        List<Long> comprados = new ArrayList<>();
        List<Long> vistos = new ArrayList<>();
        for (long i = 0; i < 200_000; i++) {
            comprados.add(i);
            if (i % 2 == 0) vistos.add(i);
        }
        List<Long> r = Solution.naoVistos(comprados, vistos);
        assertEquals(100_000, r.size());
        assertEquals(1L, r.get(0));
    }
}
